USE newsroom;
SET @db = DATABASE();

SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='users' AND COLUMN_NAME='banned_until')=0, 'ALTER TABLE users ADD COLUMN banned_until DATETIME NULL AFTER two_factor_enabled', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='users' AND COLUMN_NAME='ban_reason')=0, 'ALTER TABLE users ADD COLUMN ban_reason VARCHAR(1000) NULL AFTER banned_until', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='users' AND COLUMN_NAME='ban_previous_name')=0, 'ALTER TABLE users ADD COLUMN ban_previous_name VARCHAR(100) NULL AFTER ban_reason', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='users' AND COLUMN_NAME='ban_previous_avatar')=0, 'ALTER TABLE users ADD COLUMN ban_previous_avatar VARCHAR(500) NULL AFTER ban_previous_name', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='articles' AND COLUMN_NAME='ban_hold')=0, 'ALTER TABLE articles ADD COLUMN ban_hold TINYINT(1) NOT NULL DEFAULT 0 AFTER status', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='articles' AND COLUMN_NAME='ban_previous_status')=0, 'ALTER TABLE articles ADD COLUMN ban_previous_status ENUM(''draft'',''review'',''published'',''rejected'') NULL AFTER ban_hold', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='articles' AND COLUMN_NAME='ban_resolution')=0, 'ALTER TABLE articles ADD COLUMN ban_resolution ENUM(''pending'',''delete'',''hide'',''restore'') NULL AFTER ban_previous_status', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='comments' AND COLUMN_NAME='ban_hold')=0, 'ALTER TABLE comments ADD COLUMN ban_hold TINYINT(1) NOT NULL DEFAULT 0 AFTER status', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='comments' AND COLUMN_NAME='ban_resolution')=0, 'ALTER TABLE comments ADD COLUMN ban_resolution ENUM(''pending'',''delete'',''hide'',''restore'') NULL AFTER ban_hold', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='auth_sessions' AND COLUMN_NAME='device_key')=0, 'ALTER TABLE auth_sessions ADD COLUMN device_key CHAR(64) NOT NULL DEFAULT '''' AFTER ip_address', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='auth_sessions' AND COLUMN_NAME='switch_token')=0, 'ALTER TABLE auth_sessions ADD COLUMN switch_token CHAR(64) NULL AFTER device_key', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
UPDATE auth_sessions SET switch_token=SHA2(CONCAT(id,UUID()),256) WHERE switch_token IS NULL OR switch_token='';
UPDATE auth_sessions SET device_key=SHA2(CONCAT(id,UUID()),256) WHERE device_key='';
DELETE s1 FROM auth_sessions s1 JOIN auth_sessions s2 ON s1.user_id=s2.user_id AND s1.device_key=s2.device_key AND s1.id<s2.id;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='auth_sessions' AND INDEX_NAME='idx_auth_sessions_switch_token')=0, 'CREATE UNIQUE INDEX idx_auth_sessions_switch_token ON auth_sessions(switch_token)', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='auth_sessions' AND INDEX_NAME='uq_auth_sessions_device_user')=0, 'CREATE UNIQUE INDEX uq_auth_sessions_device_user ON auth_sessions(user_id,device_key)', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
